int components(Graph *G) {
    int cnt = 0;
    for (int v = 0; v < G->n; ++v) visited[v] = 0;     /* 清空标记 */

    for (int v = 0; v < G->n; ++v) {
        if (visited[v]) continue;                      /* 已属前面某个分量 */
        ++cnt;                                          /* 启动一次 = 新分量 */
        /* 从 v 出发做一次 BFS（DFS 亦可） */
        int q[MAXV], head = 0, tail = 0;
        visited[v] = 1; q[tail++] = v;
        while (head < tail) {
            int u = q[head++];
            printf("%d ", u);                           /* 输出本分量顶点 */
            for (ArcNode *p = G->v[u].first; p; p = p->next)
                if (!visited[p->adjTo]) { visited[p->adjTo] = 1; q[tail++] = p->adjTo; }
        }
        printf("\n");
    }
    return cnt;
}
